-- Imported from Masvingo_Burial_Society.pdf.
-- Unclear names and phone numbers are intentionally blank.
-- Members can be linked after registration using a verified phone number or name.

create table if not exists public.burial_society_member_registry (
  id text primary key,
  source_number integer not null,
  full_name text not null default '',
  phone text not null default '',
  amount_paid text not null default '',
  linked boolean not null default false,
  linked_member_id text,
  linked_auth_user_id uuid,
  source text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.burial_society_member_registry enable row level security;
drop policy if exists "Admins can manage burial registry" on public.burial_society_member_registry;
create policy "Admins can manage burial registry" on public.burial_society_member_registry
  for all using (public.is_cyberlyx_admin()) with check (public.is_cyberlyx_admin());

on conflict (id) do update set
  source_number = excluded.source_number,
  full_name = excluded.full_name,
  phone = excluded.phone,
  amount_paid = excluded.amount_paid,
  source = excluded.source,
  updated_at = now();
